// Package: Microsoft.Extensions.AI.Ollama --version 9.*
// Install Ollama and run: ollama pull llama3
// Install Ollama and run: ollama pull nomic-embed-text

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Ollama;

var endpoint = new Uri("http://localhost:11434");

// Chat client for local Llama 3
var chatClient = new OllamaChatClient(endpoint, "llama3");

var response = await chatClient.GetResponseAsync(
    [new ChatMessage(ChatRole.User, "What is RAG?")],
    cancellationToken: ct);

Console.WriteLine(response.Messages.Last().Text);
// Expected: A grounded answer generated locally without cloud APIs.

// Embedding generator for local embedding model
var embeddingGenerator = new OllamaEmbeddingGenerator(endpoint, "nomic-embed-text");

var embedding = await embeddingGenerator.GenerateAsync("RAG combines retrieval with generation.", ct);
Console.WriteLine($"Embedding dimensions: {embedding.Vector.Length}");
// Expected: Embedding dimensions: 768 (or model-dependent)

// Use with the same RagService abstraction as cloud providers
var ragService = new RagService(embeddingGenerator, vectorStore, chatClient);
var answer = await ragService.AnswerAsync("What is RAG?");
Console.WriteLine(answer);
